// app/articles/[id]/page.tsx — серверный компонент,
// fetch выполняется на сервере, HTML приходит уже готовым
export default async function ArticlePage({ params }: { params: { id: string } }) {
  const article = await fetch(`https://api.example.com/articles/${params.id}`, {
    next: { revalidate: 60 }, // ISR: пересобирать не чаще раза в минуту
  }).then((r) => r.json());

  return <article>{article.title}</article>;
}

