// Rust-функция, скомпилированная в Wasm через wasm-bindgen
#[wasm_bindgen]
pub fn fibonacci(n: u32) -> u64 {
    match n {
        0 | 1 => n as u64,
        _ => fibonacci(n - 1) + fibonacci(n - 2),
    }
}

